<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/auth.php'; require_login(); require_once __DIR__ . '/../includes/db.php';
$bookingId = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT); $userId = current_user_id();
$stmt = $conn->prepare(
    "SELECT sb.*, s.title, s.description, s.user_id AS owner_id,
            owner.F_name AS owner_first, owner.m_name AS owner_middle, owner.L_name AS owner_last, owner.phone AS owner_phone,
            learner.F_name AS learner_first, learner.m_name AS learner_middle, learner.L_name AS learner_last, learner.phone AS learner_phone,
            r.rating, r.comment, r.review_date, r.user_id AS reviewer_id
     FROM `SESSION_BOOKING` sb
     JOIN `SKILL` s ON s.skill_id = sb.skill_id
     JOIN `USER` owner ON owner.user_id = s.user_id
     JOIN `USER` learner ON learner.user_id = sb.bookedByUser
     LEFT JOIN `REVIEW` r ON r.booking_id = sb.booking_id
     WHERE sb.booking_id = ? LIMIT 1"
); $stmt->bind_param('i', $bookingId); $stmt->execute(); $booking = $stmt->get_result()->fetch_assoc();
if (!$booking || ((int)$booking['bookedByUser'] !== $userId && (int)$booking['owner_id'] !== $userId && ($_SESSION['role'] ?? '') !== 'admin')) { http_response_code(404); exit('Booking not found.'); }
$isLearner = (int)$booking['bookedByUser'] === $userId; $isOwner = (int)$booking['owner_id'] === $userId; $canReview = $isLearner && $booking['session_status'] === 'completed' && $booking['rating'] === null;
$pageTitle = 'Session details'; require __DIR__ . '/../includes/header.php';
?>
<section class="py-4 py-lg-5"><div class="container" style="max-width: 960px">
    <div class="d-flex justify-content-between align-items-end mb-4"><div><div class="eyebrow text-primary mb-1">Booking #<?= (int)$booking['booking_id'] ?></div><h1 class="section-title h2 mb-0"><?= e($booking['title']) ?></h1></div><span class="badge fs-6 text-bg-<?= e(status_class($booking['session_status'])) ?>"><?= e(ucfirst($booking['session_status'])) ?></span></div>
    <div class="row g-4"><div class="col-lg-7"><div class="surface-card p-4 mb-4"><h2 class="h5 mb-4">Session overview</h2><div class="booking-timeline"><div class="mb-4"><div class="text-secondary small">Scheduled for</div><strong><?= e(format_datetime($booking['session_slot'])) ?></strong></div><div class="mb-4"><div class="text-secondary small">Mentor</div><strong><?= e(trim($booking['owner_first'].' '.$booking['owner_middle'].' '.$booking['owner_last'])) ?></strong></div><div><div class="text-secondary small">Learner</div><strong><?= e(trim($booking['learner_first'].' '.$booking['learner_middle'].' '.$booking['learner_last'])) ?></strong></div></div><?php if ($booking['meeting_link']): ?><a class="btn btn-primary mt-4" href="<?= e($booking['meeting_link']) ?>" target="_blank" rel="noopener"><i class="bi bi-camera-video me-1"></i>Open meeting link</a><?php endif; ?></div>
        <?php if ($booking['rating'] !== null): ?><div class="surface-card p-4"><div class="d-flex justify-content-between"><h2 class="h5">Session review</h2><span class="rating-stars"><?php for($i=0;$i<5;$i++): ?><i class="bi bi-star<?= $i < (int)$booking['rating'] ? '-fill' : '' ?>"></i><?php endfor; ?></span></div><p class="text-secondary mb-0"><?= e($booking['comment'] ?: 'No written comment.') ?></p></div><?php elseif ($canReview): ?><div class="surface-card p-4"><h2 class="h5">Review this session</h2><form method="post" action="<?= e(url('actions/submit_review.php')) ?>"><?= csrf_field() ?><input type="hidden" name="booking_id" value="<?= (int)$booking['booking_id'] ?>"><div class="mb-3"><label class="form-label" for="rating">Rating: <strong id="ratingOutput">5/5</strong></label><input class="form-range" id="rating" name="rating" type="range" min="1" max="5" value="5" data-rating-input="#ratingOutput"></div><div class="mb-3"><label class="form-label" for="comment">Comment</label><textarea class="form-control" id="comment" name="comment" rows="4" maxlength="2000"></textarea></div><button class="btn btn-primary" type="submit">Submit review</button></form></div><?php endif; ?>
    </div><div class="col-lg-5"><div class="surface-card p-4 mb-4"><h2 class="h5">Status and payment</h2><dl class="row small mb-0"><dt class="col-6 text-secondary">Session</dt><dd class="col-6 text-end"><?= e(ucfirst($booking['session_status'])) ?></dd><dt class="col-6 text-secondary">Payment</dt><dd class="col-6 text-end"><?= e(ucfirst($booking['payment_status'] ?: 'unpaid')) ?></dd></dl></div>
        <?php if ($isOwner || ($_SESSION['role'] ?? '') === 'admin'): ?><form class="surface-card p-4" method="post" action="<?= e(url('actions/update_booking_status.php')) ?>"><h2 class="h5">Manage request</h2><?= csrf_field() ?><input type="hidden" name="booking_id" value="<?= (int)$booking['booking_id'] ?>"><div class="mb-3"><label class="form-label" for="session_status">Session status</label><select class="form-select" id="session_status" name="session_status"><?php foreach(allowed_session_statuses() as $status): ?><option value="<?= e($status) ?>"<?= selected($status,$booking['session_status']) ?>><?= e(ucfirst($status)) ?></option><?php endforeach; ?></select></div><div class="mb-3"><label class="form-label" for="payment_status">Payment status</label><select class="form-select" id="payment_status" name="payment_status"><?php foreach(allowed_payment_statuses() as $status): ?><option value="<?= e($status) ?>"<?= selected($status,$booking['payment_status']) ?>><?= e(ucfirst($status)) ?></option><?php endforeach; ?></select></div><div class="mb-3"><label class="form-label" for="meeting_link">Meeting link</label><input class="form-control" id="meeting_link" name="meeting_link" type="url" maxlength="255" value="<?= e($booking['meeting_link']) ?>"></div><button class="btn btn-primary w-100" type="submit">Update booking</button></form><?php elseif ($isLearner && in_array($booking['session_status'],['pending','accepted'],true)): ?><form method="post" action="<?= e(url('actions/update_booking_status.php')) ?>"><?= csrf_field() ?><input type="hidden" name="booking_id" value="<?= (int)$booking['booking_id'] ?>"><input type="hidden" name="session_status" value="cancelled"><input type="hidden" name="payment_status" value="<?= e($booking['payment_status'] ?: 'unpaid') ?>"><button class="btn btn-outline-danger w-100" type="submit" data-confirm="Cancel this session request?">Cancel request</button></form><?php endif; ?>
    </div></div>
</div></section>
<?php require __DIR__ . '/../includes/footer.php'; ?>
